/*
 * The hands-on tutorial, stage by stage. Text uses the same little markup as the installation steps
 * (see Rich in components/Install.tsx): **bold**  `code`  [[Key]]  [label](https://link).
 * Screenshots live in public/img/workshop/ and are generated by scripts/tutorial-shots.mjs.
 */
export type Where = 'github' | 'desktop' | 'vscode' | 'terminal'

export interface Action { where: Where; text: string; cmds?: string[] }
export interface Shot { file: string; alt: string; caption: string; /** Show it after this action (1 = after the first). Default: after the last. */ after?: number }
export interface Callout { tone: 'note' | 'warn' | 'tip'; title: string; text: string }

export interface Stage {
  n: number
  slug: string
  short: string
  title: string
  /** Plain-language explanation of what this stage is for. */
  why: string
  actions: Action[]
  /** After the actions: what you should see. */
  expect: string
  shots: Shot[]
  callouts?: Callout[]
  explain?: { title: string; items: string[] }
  mistakes?: { title: string; fix: string }[]
}

export const WHERE: Record<Where, { label: string; hint: string }> = {
  github: { label: 'On GitHub', hint: 'In your web browser' },
  desktop: { label: 'On your computer', hint: 'Files and folders' },
  vscode: { label: 'In VS Code', hint: 'The editor window' },
  terminal: { label: 'In the terminal', hint: 'Type, then press Enter' },
}

const REPO = 'my-first-git-project'
const URL_EXAMPLE = `https://github.com/{{ghuser}}/${REPO}.git`
